ALTER TABLE employee_face_profiles ADD COLUMN status text NOT NULL DEFAULT 'LEGACY', ADD COLUMN review_ciphertext text, ADD COLUMN approved_by uuid, ADD COLUMN approved_at timestamp(3);
CREATE TABLE face_capture_challenges (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, employee_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, purpose text NOT NULL, turn text NOT NULL, expires_at timestamp(3) NOT NULL, used_at timestamp(3), created_at timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenant_id,employee_id) REFERENCES employees(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX face_challenge_employee_idx ON face_capture_challenges(tenant_id,employee_id,created_at);
